50	func newCheckpointDeleteCmdWithPrompts(prompts checkpointDeletePrompts) *cobra.Command {
51		var flags checkpointDeleteFlags
52	
53		cmd := &cobra.Command{
54			Use:   "delete <checkpoint-id>",
55			Short: "Delete a checkpoint locally and from checkpoint remotes",
56			Long: `Delete one checkpoint from this repository and from every checkpoint remote
57	that holds it.
58	
59	The full checkpoint ID is required; prefixes are not accepted. Deleting from a
60	remote cannot be undone. A checkpoint on the entire/checkpoints/v1 branch is
61	removed from the branch tip only: the branch's history still contains it.
62	
63	With --local-only no remote is contacted, except on the git-branch backend:
64	there a local removal reaches the sync remote on the next git push, so that
65	remote is checked, and --local-only (or a selection that leaves it out) is
66	refused while it holds a copy or cannot be reached. With push_sessions
67	disabled the removal is not pushed, but re-enabling it later pushes it.
68	
69	Other checkpoints of the same sessions are listed but not deleted. Each one
70	carries the session's full transcript, so the session stays visible on
71	entire.com while any of them remain.
72	
73	Without --force the command asks for confirmation, and refuses when it cannot
74	prompt. --dry-run prints what would be deleted and changes nothing.
75	
76	Examples:
77	  entire checkpoint delete <id> --dry-run
78	  entire checkpoint delete <id>
79	  entire checkpoint delete <id> --remote origin --force
80	  entire checkpoint delete <id> --local-only --force`,
81			Args: cobra.ExactArgs(1),
82			RunE: func(cmd *cobra.Command, args []string) error {
83				cmd.SilenceUsage = true
84				return runCheckpointDelete(cmd, args[0], flags, prompts.canPrompt(), prompts.selectTargets)
85			},
86		}
87	
88		cmd.Flags().BoolVar(&flags.dryRun, "dry-run", false, "Print what would be deleted without changing anything")
89		cmd.Flags().BoolVarP(&flags.force, "force", "f", false, "Delete without asking for confirmation")
90		cmd.Flags().BoolVar(&flags.localOnly, "local-only", false, "Delete only the local copy; leave every remote untouched")
91		cmd.Flags().StringArrayVar(&flags.remotes, "remote", nil, "Limit remote deletion to this remote; the local copy is still deleted (repeatable; \""+strategy.CheckpointRemoteTargetName+"\" names the dedicated checkpoint remote)")
92		cmd.Flags().BoolVar(&flags.json, "json", false, "Output as JSON")
93		return cmd
94	}
