96	func validateCheckpointDeleteFlags(flags checkpointDeleteFlags) error {
97		if flags.localOnly && len(flags.remotes) > 0 {
98			return errors.New("--local-only cannot be combined with --remote")
99		}
100		if flags.json && !flags.dryRun && !flags.force {
101			return errors.New("--json without --dry-run requires --force, since it cannot prompt")
102		}
103		return nil
104	}
