106	func runCheckpointDelete(cmd *cobra.Command, rawID string, flags checkpointDeleteFlags, canPrompt bool, selectTargets checkpointDeleteTargetSelector) error {
107		ctx := cmd.Context()
108		out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()
109		if err := validateCheckpointDeleteFlags(flags); err != nil {
110			return err
111		}
112		cid, err := id.NewCheckpointID(rawID)
113		if err != nil {
114			return fmt.Errorf("invalid checkpoint ID %q: pass the full ID (prefixes are not accepted)", rawID)
115		}
116		if checkDisabledGuard(ctx, errOut) {
117			return NewSilentError(errors.New("entire is disabled in this repository"))
118		}
119	
120		plan, err := strategy.PlanCheckpointDelete(ctx, cid, strategy.CheckpointDeletePlanOptions{LocalOnly: flags.localOnly})
121		if err != nil {
122			if flags.json && plan != nil && errors.Is(err, strategy.ErrCheckpointDeleteNotFound) {
123				doc := buildCheckpointDeleteJSON(plan, nil, nil, flags.dryRun, flags.localOnly)
124				doc.NotFound = true
125				if writeErr := writeCheckpointDeleteJSON(out, doc); writeErr != nil {
126					return writeErr
127				}
128				return NewSilentError(fmt.Errorf("delete checkpoint: %w", err))
129			}
130			return fmt.Errorf("delete checkpoint: %w", err)
131		}
132		targets, err := selectCheckpointDeleteTargets(plan, flags)
133		if err != nil {
134			return err
135		}
136		selection := checkpointDeleteSelection(flags)
137	
138		if flags.dryRun {
139			refusal := plan.CheckLocalV1Propagation(targets, selection)
140			if flags.json {
141				doc := buildCheckpointDeleteJSON(plan, targets, nil, true, flags.localOnly)
142				if refusal != nil {
143					doc.Refusal = refusal.Error()
144				}
145				return writeCheckpointDeleteJSON(out, doc)
146			}
147			printCheckpointDeletePlan(out, plan, targets, flags.localOnly)
148			if refusal != nil {
149				fmt.Fprintf(out, "\nThis delete would be refused: %s\n", refusal)
150			}
151			fmt.Fprintln(out, "\nDry run: nothing was changed.")
152			return nil
153		}
154	
155		if active := plan.ActiveStates(); len(active) > 0 && !flags.force {
156			return fmt.Errorf("refusing to delete checkpoint %s: session %s is still active; end the session first or pass --force", cid, active[0].SessionID)
157		}
158		if !plan.HasLocalCopy() && len(targets) == 0 {
159			return fmt.Errorf("checkpoint %s has no local copy and no selected remote holds it; nothing to delete", cid)
160		}
161		if err := plan.CheckLocalV1Propagation(targets, selection); err != nil {
162			return err //nolint:wrapcheck // names the checkpoint and the remedy already
163		}
164	
165		if !flags.json {
166			printCheckpointDeletePlan(out, plan, targets, flags.localOnly)
167			fmt.Fprintln(out)
168		}
169		if !flags.force && canPrompt && len(targets) > 1 {
170			targets, err = selectTargets(ctx, targets)
171			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
172				fmt.Fprintln(out, "Deletion cancelled.")
173				return nil
174			}
175			if err != nil {
176				return err
177			}
178			selection = strategy.SelectionPrompt
179			if !plan.HasLocalCopy() && len(targets) == 0 {
180				fmt.Fprintln(out, "No remote selected and there is no local copy; deletion cancelled.")
181				return nil
182			}
183			if err := plan.CheckLocalV1Propagation(targets, selection); err != nil {
184				return err //nolint:wrapcheck // names the checkpoint and the remedy already
185			}
186		}
187		confirmed, err := confirmControlPlaneDeletion(ctx, out, "checkpoint "+cid.String(), flags.force, canPrompt)
188		if err != nil || !confirmed {
189			return err
190		}
191	
192		result, execErr := strategy.ExecuteCheckpointDelete(ctx, plan, strategy.CheckpointDeleteOptions{Targets: targets, LocalOnly: flags.localOnly, Selection: selection})
193		if flags.json && result != nil {
194			if err := writeCheckpointDeleteJSON(out, buildCheckpointDeleteJSON(plan, targets, result, false, flags.localOnly)); err != nil {
195				return err
196			}
197		} else if result != nil {
198			printCheckpointDeleteResult(out, plan, targets, result, flags)
199		}
200		if execErr != nil {
201			return fmt.Errorf("delete checkpoint %s: %w", cid, execErr)
202		}
203		if result.Failed() {
204			for _, t := range result.Targets {
205				if t.Failed() {
206					fmt.Fprintf(errOut, "Failed to delete checkpoint %s from %s: %s\n  Retry: %s\n", cid, t.Target.Name(), t.Error, checkpointDeleteRetryCommand(cid, t.Target))
207				}
208			}
209			return NewSilentError(fmt.Errorf("checkpoint %s was not deleted from every remote", cid))
210		}
211		return nil
212	}
