214	// checkpointDeleteSelection names how the flags chose the targets.
215	func checkpointDeleteSelection(flags checkpointDeleteFlags) strategy.CheckpointDeleteSelection {
216		switch {
217		case flags.localOnly:
218			return strategy.SelectionLocalOnly
219		case len(flags.remotes) > 0:
220			return strategy.SelectionRemoteFlag
221		default:
222			return strategy.SelectionAllHolders
223		}
224	}
