226	// selectCheckpointDeleteTargets picks the remote targets a delete acts on:
227	// none with --local-only, the named ones with --remote, else every reachable
228	// target that holds the checkpoint. A --remote name that matches no known
229	// checkpoint remote is an error rather than a silent no-op.
230	func selectCheckpointDeleteTargets(plan *strategy.CheckpointDeletePlan, flags checkpointDeleteFlags) ([]strategy.CheckpointDeleteTarget, error) {
231		if flags.localOnly {
232			return nil, nil
233		}
234		holders := plan.HolderTargets()
235		if len(flags.remotes) == 0 {
236			return holders, nil
237		}
238		var known []string
239		for _, t := range plan.Targets {
240			known = append(known, t.Remotes...)
241		}
242		for _, name := range flags.remotes {
243			if !slices.Contains(known, name) {
244				slices.Sort(known)
245				return nil, fmt.Errorf("--remote %q is not a checkpoint remote of this repository (known: %s)", name, strings.Join(slices.Compact(known), ", "))
246			}
247		}
248		var selected []strategy.CheckpointDeleteTarget
249		for _, t := range holders {
250			for _, name := range t.Remotes {
251				if slices.Contains(flags.remotes, name) {
252					selected = append(selected, t)
253					break
254				}
255			}
256		}
257		return selected, nil
258	}
