260	func promptCheckpointDeleteTargets(ctx context.Context, targets []strategy.CheckpointDeleteTarget) ([]strategy.CheckpointDeleteTarget, error) {
261		options := make([]huh.Option[int], len(targets))
262		selected := make([]int, len(targets))
263		for i, t := range targets {
264			options[i] = huh.NewOption(fmt.Sprintf("%s (%s)", strings.Join(t.Remotes, ", "), t.Display()), i).Selected(true)
265			selected[i] = i
266		}
267		form := NewAccessibleForm(huh.NewGroup(
268			huh.NewMultiSelect[int]().
269				Title("Delete the checkpoint from these remotes").
270				Description("Use space to toggle, enter to confirm.").
271				Options(options...).
272				Value(&selected),
273		))
274		if err := form.RunWithContext(ctx); err != nil {
275			return nil, fmt.Errorf("remote selection: %w", err)
276		}
277		chosen := make([]strategy.CheckpointDeleteTarget, 0, len(selected))
278		for _, i := range selected {
279			chosen = append(chosen, targets[i])
280		}
281		return chosen, nil
282	}
