288	func printCheckpointDeletePlan(w io.Writer, plan *strategy.CheckpointDeletePlan, targets []strategy.CheckpointDeleteTarget, localOnly bool) {
289		fmt.Fprintf(w, "Checkpoint %s\n", plan.CheckpointID)
290	
291		fmt.Fprintln(w, "\nLocal:")
292		if !plan.HasLocalCopy() {
293			fmt.Fprintln(w, "  not in this clone")
294		}
295		if plan.LocalRef != "" {
296			fmt.Fprintf(w, "  ref %s\n", plan.LocalRef)
297		}
298		if plan.LocalV1 {
299			fmt.Fprintf(w, "  %s branch\n", paths.MetadataBranchName)
300		}
301		for _, name := range plan.TrackingV1 {
302			fmt.Fprintf(w, "  remote-tracking %s (stays until %s's copy is deleted)\n", trackingV1RefName(name), name)
303		}
304	
305		fmt.Fprintln(w, "\nRemotes:")
306		if len(plan.Targets) == 0 {
307			fmt.Fprintln(w, "  none configured")
308		}
309		for _, t := range plan.Targets {
310			fmt.Fprintf(w, "  %s (%s): %s%s\n", strings.Join(t.Remotes, ", "), t.Display(), describeDeleteTarget(t), selectionNote(t, targets, localOnly))
311		}
312	
313		if len(plan.Sessions) > 0 {
314			fmt.Fprintln(w, "\nSessions in this checkpoint (their token counts are removed with it):")
315			for _, s := range plan.Sessions {
316				fmt.Fprintf(w, "  %s  %s  input %d, output %d tokens\n", s.SessionID, s.Agent, s.InputTokens, s.OutputTokens)
317			}
318		}
319		if len(plan.SessionStates) > 0 {
320			fmt.Fprintln(w, "\nLocal session state to clear:")
321			for _, s := range plan.SessionStates {
322				status := ""
323				if s.Active {
324					status = " (session still active)"
325				}
326				fmt.Fprintf(w, "  %s: %s%s\n", s.SessionID, strings.Join(s.Fields, ", "), status)
327			}
328		}
329		if len(plan.OtherLocalCheckpoints) > 0 {
330			fmt.Fprintln(w, "\nOther local checkpoints of these sessions (not deleted; this list is local only,")
331			fmt.Fprintln(w, "and the sessions stay visible on entire.com while these remain):")
332			for _, o := range plan.OtherLocalCheckpoints {
333				fmt.Fprintf(w, "  %s  %s\n", o.CheckpointID, strings.Join(o.SessionIDs, ", "))
334			}
335			if plan.OtherLocalTruncated {
336				fmt.Fprintln(w, "  (scan truncated; there may be more)")
337			}
338		}
339		if checkpointDeleteTouchesV1(plan, targets, localOnly) {
340			fmt.Fprintf(w, "\nNote: on the %s branch the checkpoint is removed from the tip only; its content stays in the branch history.\n", paths.MetadataBranchName)
341		}
342		if plan.PushSessionsDisabled && !localOnly {
343			fmt.Fprintln(w, "Note: push_sessions is disabled, but the delete still removes the copies on the selected remotes.")
344		}
345		for _, warning := range plan.Warnings {
346			fmt.Fprintf(w, "Warning: %s\n", warning)
347		}
348	}
