354	func describeDeleteTarget(t strategy.CheckpointDeleteTarget) string {
355		if t.NotChecked {
356			return "not checked (--local-only)"
357		}
358		if !t.Reachable {
359			return "unreachable"
360		}
361		var parts []string
362		if !t.RefOID.IsZero() {
363			parts = append(parts, "ref")
364		}
365		switch t.V1 {
366		case strategy.V1CopyPresent:
367			parts = append(parts, paths.MetadataBranchName)
368		case strategy.V1CopyUnknown:
369			parts = append(parts, paths.MetadataBranchName+" (verified when deleting)")
370		case strategy.V1CopyAbsent:
371		}
372		if len(parts) == 0 {
373			return "does not hold it"
374		}
375		return "holds " + strings.Join(parts, ", ")
376	}
