378	func selectionNote(t strategy.CheckpointDeleteTarget, selected []strategy.CheckpointDeleteTarget, localOnly bool) string {
379		if !t.HoldsCheckpoint() {
380			return ""
381		}
382		if localOnly || !slices.ContainsFunc(selected, func(s strategy.CheckpointDeleteTarget) bool { return s.URL == t.URL }) {
383			return " (not selected)"
384		}
385		return ""
386	}
