388	// checkpointDeleteTouchesV1 reports whether this delete removes a v1 copy,
389	// leaving its content in that branch's history: the local branch, or a
390	// selected remote's.
391	func checkpointDeleteTouchesV1(plan *strategy.CheckpointDeletePlan, targets []strategy.CheckpointDeleteTarget, localOnly bool) bool {
392		if plan.LocalV1 {
393			return true
394		}
395		if localOnly {
396			return false
397		}
398		return slices.ContainsFunc(targets, func(t strategy.CheckpointDeleteTarget) bool {
399			return t.V1 == strategy.V1CopyPresent || t.V1 == strategy.V1CopyUnknown
400		})
401	}
