403	func printCheckpointDeleteResult(w io.Writer, plan *strategy.CheckpointDeletePlan, selected []strategy.CheckpointDeleteTarget, result *strategy.CheckpointDeleteResult, flags checkpointDeleteFlags) {
404		fmt.Fprintf(w, "Local ref: %s\n", result.LocalRef)
405		if plan.LocalV1 {
406			fmt.Fprintf(w, "Local %s: %s\n", paths.MetadataBranchName, result.LocalV1)
407		}
408		for _, t := range result.Targets {
409			line := fmt.Sprintf("%s: ref %s", t.Target.Name(), t.Ref)
410			if t.V1 != strategy.DeleteOutcomeAbsent {
411				line += fmt.Sprintf(", %s %s", paths.MetadataBranchName, t.V1)
412			}
413			fmt.Fprintln(w, line)
414		}
415		if result.Failed() {
416			return
417		}
418		notSelected := unselectedHolderNames(plan, selected)
419		notChecked := notCheckedTargetNames(plan)
420		unreachable := unreachableTargetNames(plan, flags)
421		if len(notSelected) == 0 && len(notChecked) == 0 && len(unreachable) == 0 {
422			fmt.Fprintf(w, "Deleted checkpoint %s.\n", plan.CheckpointID)
423			return
424		}
425		if flags.localOnly {
426			fmt.Fprintf(w, "Deleted the local copy of checkpoint %s.\n", plan.CheckpointID)
427		} else {
428			fmt.Fprintf(w, "Deleted checkpoint %s from the selected locations.\n", plan.CheckpointID)
429		}
430		for _, name := range notSelected {
431			fmt.Fprintf(w, "Still on %s (not selected).\n", name)
432		}
433		for _, name := range notChecked {
434			fmt.Fprintf(w, "%s was not checked (--local-only) and may still hold it.\n", name)
435		}
436		if len(unreachable) > 0 {
437			fmt.Fprintf(w, "Could not check %s, which may still hold it; retry with:\n", strings.Join(unreachable, ", "))
438			for _, name := range unreachable {
439				fmt.Fprintf(w, "  entire checkpoint delete %s --remote %s\n", plan.CheckpointID, name)
440			}
441		}
442	}
