444	// unselectedHolderNames names the reachable holders this delete left alone:
445	// excluded by --remote or --local-only, or deselected at the prompt. Remotes
446	// --local-only did not probe are covered by notCheckedTargetNames.
447	func unselectedHolderNames(plan *strategy.CheckpointDeletePlan, selected []strategy.CheckpointDeleteTarget) []string {
448		var names []string
449		for _, t := range plan.HolderTargets() {
450			if !slices.ContainsFunc(selected, func(s strategy.CheckpointDeleteTarget) bool { return s.URL == t.URL }) {
451				names = append(names, t.Name())
452			}
453		}
454		return names
455	}
456	
457	func notCheckedTargetNames(plan *strategy.CheckpointDeletePlan) []string {
458		var names []string
459		for _, t := range plan.Targets {
460			if t.NotChecked {
461				names = append(names, t.Name())
462			}
463		}
464		return names
465	}
466	
467	// unreachableTargetNames names the targets the probe could not reach. An
468	// unreachable remote is a warning, never a failure, but the summary must not
469	// claim the checkpoint is gone everywhere while one of them may still hold it.
470	func unreachableTargetNames(plan *strategy.CheckpointDeletePlan, flags checkpointDeleteFlags) []string {
471		var names []string
472		for _, t := range plan.Targets {
473			if t.Reachable || t.NotChecked {
474				continue
475			}
476			if len(flags.remotes) > 0 && !slices.ContainsFunc(t.Remotes, func(n string) bool { return slices.Contains(flags.remotes, n) }) {
477				continue
478			}
479			names = append(names, t.Name())
480		}
481		return names
482	}
