549	func buildCheckpointDeleteJSON(plan *strategy.CheckpointDeletePlan, targets []strategy.CheckpointDeleteTarget, result *strategy.CheckpointDeleteResult, dryRun, localOnly bool) checkpointDeleteJSON {
550		doc := checkpointDeleteJSON{
551			CheckpointID:         plan.CheckpointID.String(),
552			DryRun:               dryRun,
553			Local:                checkpointDeleteLocalJSON{Ref: plan.LocalRef.String(), V1: plan.LocalV1, TrackingV1: plan.TrackingV1},
554			Remotes:              []checkpointDeleteRemoteJSON{},
555			Sessions:             []checkpointDeleteSessionJSON{},
556			SessionStates:        []checkpointDeleteStateJSON{},
557			OtherLocal:           []checkpointDeleteSiblingJSON{},
558			OtherLocalTruncated:  plan.OtherLocalTruncated,
559			V1HistoryRetained:    checkpointDeleteTouchesV1(plan, targets, localOnly),
560			PushSessionsDisabled: plan.PushSessionsDisabled,
561			Warnings:             plan.Warnings,
562		}
563		if !plan.LocalRefOID.IsZero() {
564			doc.Local.RefOID = plan.LocalRefOID.String()
565		}
566		if result != nil {
567			doc.Local.RefResult = string(result.LocalRef)
568			doc.Local.V1Result = string(result.LocalV1)
569		}
570		for _, t := range plan.Targets {
571			entry := checkpointDeleteRemoteJSON{
572				Name:     t.Name(),
573				Names:    t.Remotes,
574				URL:      t.Display(),
575				Status:   checkpointDeleteTargetStatus(t),
576				Selected: slices.ContainsFunc(targets, func(s strategy.CheckpointDeleteTarget) bool { return s.URL == t.URL }),
577			}
578			if !t.RefOID.IsZero() {
579				entry.RefOID = t.RefOID.String()
580			}
581			if t.Reachable {
582				entry.V1 = string(t.V1)
583			}
584			if result != nil {
585				for _, r := range result.Targets {
586					if r.Target.URL != t.URL {
587						continue
588					}
589					res := &checkpointDeleteRemoteResultJSON{Ref: string(r.Ref), V1: string(r.V1), Error: r.Error}
590					if r.Failed() {
591						res.Retry = checkpointDeleteRetryCommand(plan.CheckpointID, t)
592					}
593					entry.Result = res
594				}
595			}
596			doc.Remotes = append(doc.Remotes, entry)
597		}
598		for _, s := range plan.Sessions {
599			doc.Sessions = append(doc.Sessions, checkpointDeleteSessionJSON{SessionID: s.SessionID, Agent: s.Agent, InputTokens: s.InputTokens, OutputTokens: s.OutputTokens})
600		}
601		for _, s := range plan.SessionStates {
602			doc.SessionStates = append(doc.SessionStates, checkpointDeleteStateJSON{SessionID: s.SessionID, Active: s.Active, Fields: s.Fields})
603		}
604		for _, o := range plan.OtherLocalCheckpoints {
605			doc.OtherLocal = append(doc.OtherLocal, checkpointDeleteSiblingJSON{CheckpointID: o.CheckpointID.String(), SessionIDs: o.SessionIDs})
606		}
607		return doc
608	}
