610	func checkpointDeleteTargetStatus(t strategy.CheckpointDeleteTarget) string {
611		switch {
612		case t.NotChecked:
613			return "not_checked"
614		case !t.Reachable:
615			return "unreachable"
616		case t.HoldsCheckpoint():
617			return "holds"
618		default:
619			return "absent"
620		}
621	}
