623	func writeCheckpointDeleteJSON(w io.Writer, doc checkpointDeleteJSON) error {
624		data, err := json.MarshalIndent(doc, "", "  ")
625		if err != nil {
626			return fmt.Errorf("encode JSON: %w", err)
627		}
628		fmt.Fprintln(w, string(data))
629		return nil
630	}
